import{_ as t,o,c as a,a2 as s}from"./chunks/framework.Wk4ah3nE.js";const u=JSON.parse('{"title":"Threat model","description":"What Proxmox VM Autoscale exposes, what an attacker gains at each level of access, and which risks are inherent to the design versus fixable defects.","frontmatter":{"title":"Threat model","description":"What Proxmox VM Autoscale exposes, what an attacker gains at each level of access, and which risks are inherent to the design versus fixable defects.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/security/"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/security/"}],["meta",{"property":"og:title","content":"Threat model"}],["meta",{"property":"og:description","content":"What Proxmox VM Autoscale exposes, what an attacker gains at each level of access, and which risks are inherent to the design versus fixable defects."}]]},"headers":[],"relativePath":"security/index.md","filePath":"security/index.md","lastUpdated":null}'),i={name:"security/index.md"};function n(r,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h1><p>This service holds credentials for <code>root</code> on your hypervisors and executes commands against live guests. That is a high-value target. This page states plainly what it exposes, so you can decide where to run it and what to protect.</p><h2 id="what-the-service-can-do" tabindex="-1">What the service can do <a class="header-anchor" href="#what-the-service-can-do" aria-label="Permalink to &quot;What the service can do&quot;">​</a></h2><p>Given its credentials, the service can — and does — run arbitrary <code>qm</code> and <code>pvesh</code> commands as root on every node in its config. In practice it only issues <code>qm status</code>, <code>qm config</code>, <code>qm set</code> and <code>pvesh get</code>, but nothing constrains it to those. <strong>Anyone who can modify <code>config.yaml</code>, <code>autoscale.py</code> or the module files can run any command as root on every configured hypervisor.</strong></p><p>That is the core of the model. Everything else follows from it.</p><h2 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Asset</th><th>Where it lives</th><th>Exposure if compromised</th></tr></thead><tbody><tr><td>Proxmox root SSH password or key</td><td><code>config.yaml</code>, plain text</td><td>Full control of every configured node, and therefore every guest on them</td></tr><tr><td>SMTP credentials</td><td><code>config.yaml</code>, plain text</td><td>Mail relay abuse, spoofed mail from your domain</td></tr><tr><td>Gotify application token</td><td><code>config.yaml</code>, plain text</td><td>Push notifications to your operators; useful for social engineering</td></tr><tr><td>SSH private key</td><td>Path referenced in <code>config.yaml</code></td><td>Same as the password</td></tr><tr><td>The service code</td><td><code>/usr/local/bin/vm_autoscale/</code></td><td>Arbitrary root execution on all nodes at the next cycle</td></tr><tr><td>Log file</td><td><code>/var/log/vm_autoscale.log</code></td><td>VMIDs, node names, usage patterns, capacity — reconnaissance</td></tr><tr><td>Billing data</td><td><code>billing_data.json</code></td><td>Customer capacity history</td></tr></tbody></table><h2 id="attacker-positions" tabindex="-1">Attacker positions <a class="header-anchor" href="#attacker-positions" aria-label="Permalink to &quot;Attacker positions&quot;">​</a></h2><h3 id="unprivileged-local-user-on-the-autoscaler-host" tabindex="-1">Unprivileged local user on the autoscaler host <a class="header-anchor" href="#unprivileged-local-user-on-the-autoscaler-host" aria-label="Permalink to &quot;Unprivileged local user on the autoscaler host&quot;">​</a></h3><p><strong>Before the recent fix</strong>, the installer&#39;s recursive <code>chmod 755</code> left <code>config.yaml</code> world-readable — so any local user could simply read the Proxmox root password. If you installed before that change, <a href="/proxmox-vm-autoscale/security/hardening.html#verify-config-permissions">check and fix it now</a>.</p><p>After the fix, <code>config.yaml</code> is mode <code>600</code> and root-owned. What remains readable to a local user:</p><ul><li><code>/var/log/vm_autoscale.log</code>, unless you restrict it — node names, VMIDs, capacity</li><li>The service code itself (mode <code>755</code>), which reveals the config path and structure</li><li>Process arguments via <code>/proc</code>, which show the script path but no credentials</li></ul><h3 id="network-attacker-between-the-service-and-a-node" tabindex="-1">Network attacker between the service and a node <a class="header-anchor" href="#network-attacker-between-the-service-and-a-node" aria-label="Permalink to &quot;Network attacker between the service and a node&quot;">​</a></h3><p>The SSH client uses an <strong>auto-add host key policy</strong>: any host key presented is trusted, and no pinning is performed on subsequent connections. An attacker able to intercept or redirect the connection can present their own key and receive the root password or complete a key-based handshake against their own server.</p><p>This is the most serious design-level exposure. It is inherent to the current implementation, not a misconfiguration. Mitigate at the network layer — see <a href="/proxmox-vm-autoscale/security/hardening.html#pin-ssh-host-keys">hardening</a>.</p><h3 id="root-on-the-autoscaler-host" tabindex="-1">Root on the autoscaler host <a class="header-anchor" href="#root-on-the-autoscaler-host" aria-label="Permalink to &quot;Root on the autoscaler host&quot;">​</a></h3><p>Total compromise of every configured hypervisor. There is no additional boundary: the credentials are readable, the code is modifiable, and the next cycle executes whatever it now says.</p><p>Treat the autoscaler host as being in the <strong>same trust zone as the hypervisors themselves</strong>. Running it on a general-purpose jump box that other people use is a mistake.</p><h3 id="someone-who-can-open-a-pull-request" tabindex="-1">Someone who can open a pull request <a class="header-anchor" href="#someone-who-can-open-a-pull-request" aria-label="Permalink to &quot;Someone who can open a pull request&quot;">​</a></h3><p>Merged code runs as root on hypervisors at the next service restart. The installer clones <code>main</code> directly, so anything merged reaches installations that reinstall. Review contributions with that in mind.</p><h3 id="compromise-of-the-installation-path" tabindex="-1">Compromise of the installation path <a class="header-anchor" href="#compromise-of-the-installation-path" aria-label="Permalink to &quot;Compromise of the installation path&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/.../main/install.sh)</span></span></code></pre></div><p>This executes whatever is on <code>main</code> at that moment, as root, with no signature and no checksum. A compromised GitHub account, a malicious merge, or a TLS interception all lead to root execution. It is the recommended install method in the README, and it is a real supply-chain exposure. Read the script first, or <a href="/proxmox-vm-autoscale/guide/installation.html#option-b-manual-install">install manually</a>.</p><h2 id="design-level-exposures" tabindex="-1">Design-level exposures <a class="header-anchor" href="#design-level-exposures" aria-label="Permalink to &quot;Design-level exposures&quot;">​</a></h2><p>These are properties of how the service works. They are not going to be fixed by tightening a permission.</p><table tabindex="0"><thead><tr><th>Exposure</th><th>Why it exists</th><th>Can you mitigate it?</th></tr></thead><tbody><tr><td><strong>Root SSH required</strong></td><td>Every action is a <code>qm</code> command</td><td>Not today; there is no least-privilege mode</td></tr><tr><td><strong>Credentials in plain text</strong></td><td>No secrets backend</td><td>File permissions and disk encryption only</td></tr><tr><td><strong>Auto-add host keys</strong></td><td>Paramiko <code>AutoAddPolicy</code></td><td>Network segmentation, dedicated management VLAN</td></tr><tr><td><strong>Service runs unconfined as root</strong></td><td>Shipped unit sets <code>User=root</code> with no sandboxing</td><td>Yes — <a href="/proxmox-vm-autoscale/security/hardening.html#confine-the-systemd-unit">systemd drop-in</a></td></tr><tr><td><strong>VMIDs interpolated into shell strings</strong></td><td>No validation on <code>vm_id</code></td><td>Config is admin-controlled, so not remotely exploitable</td></tr><tr><td><strong>No audit trail beyond the log</strong></td><td>No structured events</td><td>Ship the log somewhere append-only</td></tr></tbody></table><h2 id="what-is-not-a-risk" tabindex="-1">What is not a risk <a class="header-anchor" href="#what-is-not-a-risk" aria-label="Permalink to &quot;What is not a risk&quot;">​</a></h2><p>Worth stating, to keep attention where it belongs:</p><ul><li><strong>No network listener.</strong> The service binds nothing. It cannot be reached from outside; it only makes outbound connections.</li><li><strong>No inbound API, no web UI, no authentication surface.</strong></li><li><strong>No guest agent.</strong> Nothing is installed inside your VMs.</li><li><strong>Outbound connections are limited</strong> to SSH to configured nodes, HTTPS to your Gotify server, and SMTP to your relay.</li><li><strong>No telemetry.</strong> The service phones nothing home. See <a href="/proxmox-vm-autoscale/privacy.html">privacy</a>.</li></ul><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>Three direct dependencies: <code>paramiko</code>, <code>PyYAML</code>, <code>requests</code>. All eight historical Dependabot alerts on this repository — mostly in <code>cryptography</code>, Paramiko&#39;s transitive dependency — are resolved. Dependabot runs weekly on pip.</p><p>Keep them current:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paramiko</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PyYAML</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip-audit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip-audit</span></span></code></pre></div><h2 id="recommended-posture" tabindex="-1">Recommended posture <a class="header-anchor" href="#recommended-posture" aria-label="Permalink to &quot;Recommended posture&quot;">​</a></h2><ol><li>Run it on a dedicated host, or on a Proxmox node itself — not on a shared jump box.</li><li>Use key authentication with a dedicated RSA key used for nothing else.</li><li>Keep management SSH on a segmented network.</li><li>Apply the <a href="/proxmox-vm-autoscale/security/hardening.html#confine-the-systemd-unit">systemd hardening drop-in</a>.</li><li>Verify <code>config.yaml</code> is <code>600</code> and root-owned after every install or upgrade.</li><li>Ship logs off-host if you need an audit trail.</li><li>Subscribe to releases so security fixes reach you.</li></ol><p>Full step-by-step: the <a href="/proxmox-vm-autoscale/security/hardening.html">hardening guide</a>. To report something: <a href="/proxmox-vm-autoscale/security/disclosure.html">responsible disclosure</a>.</p>`,36)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
